// Normalizes BOTH the success output and the HTTP node's own error output
// (onError: continueErrorOutput) into the single { ok, imageBase64, mime } / { ok:false, error } contract.
const data = $json;

// Case 1: this item came from the HTTP Request node's ERROR output.
if (data && data.error) {
  const err = data.error;
  const message = typeof err === 'string'
    ? err
    : (err.message || err.description || JSON.stringify(err));
  return { json: { ok: false, error: String(message) } };
}

// Case 2: successful gateway response - extract the base64 image.
// Typical OpenAI-compatible shape: { data: [ { b64_json: "..." } ], ... }
try {
  const b64 = data && data.data && data.data[0] && data.data[0].b64_json;
  if (!b64) {
    return {
      json: {
        ok: false,
        error: 'The image model did not return base64 image data. Raw response: ' + JSON.stringify(data).slice(0, 500)
      }
    };
  }
  return { json: { ok: true, imageBase64: b64, mime: 'image/png' } };
} catch (err) {
  return { json: { ok: false, error: 'Failed to parse image response: ' + err.message } };
}

// Normalizes BOTH the success output and the HTTP node's own error output
// (onError: continueErrorOutput) into the { ok:false, error } contract.
// sora-2 is always a stub response (never ok:true) - see Sticky Note.
const data = $json;

if (data && data.error) {
  const err = data.error;
  const message = typeof err === 'string'
    ? err
    : (err.message || err.description || JSON.stringify(err));
  return { json: { ok: false, error: 'Failed to start sora-2 video job: ' + String(message) } };
}

const jobId = (data && (data.id || (data.data && data.data.id))) || 'unknown';
return {
  json: {
    ok: false,
    error: 'sora-2 video generation is async and not yet wired into the auto-import flow; job id: ' + jobId
  }
};
